(async()=>{try{const api=await import('./trial-sequence.js?v=motion-v82');if(!window.motionShelterReady)await new Promise(r=>window.addEventListener('motion-shelter-ready',r,{once:true}));for(const[k,v]of Object.entries(api.trialDefaults))if(fx[k]===undefined)fx[k]=structuredClone(v);const oldPhases=phaseTimes,oldFrame=frame,oldControls=renderDepotControls,seconds=t*settings.duration,start=()=>oldPhases().end;for(const[k,file]of Object.entries(api.trialSources)){sources[k]='assets/'+file;if(!sprites[k]){const im=new Image();im.onload=()=>{base._renderKey='';};im.src=sources[k];sprites[k]=im;}}restoreAssets();globalThis.motionTagSources?.();phaseTimes=()=>{const p=oldPhases();return{...p,end:p.end+(fx.trialEnabled?api.trialDuration(fx):0)}};
frame=function(el,p){const duration=settings.duration,time=p*duration,prior=phaseTimes;try{phaseTimes=oldPhases;settings.duration=oldPhases().end;oldFrame(el,Math.min(time,settings.duration-.000001)/settings.duration);}finally{phaseTimes=prior;settings.duration=duration;}let canvas=el.querySelector('.documentaryTrial');if(!fx.trialEnabled||time<start()){if(canvas)canvas.style.display='none';return;}if(!canvas){canvas=document.createElement('canvas');canvas.width=960;canvas.height=540;canvas.className='tearCanvas documentaryTrial';canvas.style.cssText='position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:52';el.append(canvas);}canvas.style.display='block';for(const slot of Object.keys(api.trialSources)){const media=sprites[fx.trialSourceBindings[slot]||slot];if(media?.tagName==='VIDEO'&&media.readyState>=2){const starts={trialCamp:631.6,trialCampMan:631.6,trialCell:623,trialPrisoner:623,trialCourt:649.2,trialWitnessA:649.2,trialWitnessB:653.5},target=Math.max(0,api.trialState(time-start(),fx).source-(starts[slot]??595))%Math.max(.01,media.duration);if(Math.abs(media.currentTime-target)>.08)media.currentTime=target;}}api.paintTrial(canvas.getContext('2d'),Math.min(time-start(),api.trialDuration(fx)),sprites,fx);};
function refresh(){api.validateTrial(fx);const sec=t*settings.duration;syncDuration();t=Math.min(1,sec/settings.duration);saveEffects();base._renderKey='';frame(base,t);}function seek(source){openEditor();playing=false;t=(start()+api.trialSourceToLocal(source,fx))/settings.duration;frame(base,t);const scrub=document.querySelector('#scrub');if(scrub)scrub.value=t*1000;}
renderDepotControls=function(){oldControls();const host=document.querySelector('#depotControls');if(!host)return;const box=document.createElement('details');box.className='directorSection';box.innerHTML='<summary>Interrogation → evidence → trial ·09:55–10:55</summary>';host.prepend(box);const previews=document.createElement('div');previews.className='directorGrid';for(const s of api.trialStages){const b=document.createElement('button');b.className='pill';b.textContent=s.label;b.onclick=()=>seek((s.from+s.to)/2);previews.append(b);}box.append(previews);
const json=document.createElement('textarea');json.value=JSON.stringify(Object.fromEntries(Object.keys(api.trialDefaults).map(k=>[k,fx[k]])),null,2);json.setAttribute('aria-label','Trial scene settings');const apply=document.createElement('button');apply.className='pill';apply.textContent='Apply scene settings';apply.onclick=()=>{try{const v=JSON.parse(json.value);api.validateTrial(v);for(const k of Object.keys(api.trialDefaults))if(v[k]!==undefined)fx[k]=structuredClone(v[k]);refresh();renderDepotControls();}catch(e){apply.textContent=e.message;}};box.append(json,apply);
const select=document.createElement('select');for(const l of api.trialLayerCatalog)select.add(new Option(l.label,l.id));const edits=document.createElement('textarea'),update=document.createElement('button');update.className='pill';update.textContent='Apply selected object motion';function read(){edits.value=JSON.stringify(fx.trialLayerEdits[select.value]||{visible:true,x:0,y:0,scale:1,rotation:0,opacity:1,blur:0,depth:2,motion:{}},null,2);}select.onchange=read;read();update.onclick=()=>{try{const v=JSON.parse(edits.value),next={...fx.trialLayerEdits,[select.value]:v};api.validateTrial({...fx,trialLayerEdits:next});fx.trialLayerEdits=next;refresh();}catch(e){update.textContent=e.message;}};box.append(select,edits,update);
const replace=document.createElement('button');replace.className='pill';replace.textContent='Replace selected picture/video';replace.onclick=()=>{const slot=api.trialLayerCatalog.find(l=>l.id===select.value)?.slot;if(!slot)return;const picker=document.createElement('input');picker.type='file';picker.accept='image/*,video/*';picker.onchange=async()=>{const file=picker.files[0];if(!file)return;const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});const prior=sprites[slot]?.src;if(prior&&prior!==sources[slot]){const key=slot+'-archive-'+Date.now();await saveAsset(key,prior);(fx.trialReplacementHistory??=[]).push({slot,key});}if(file.type.startsWith('video/')){const v=document.createElement('video');v.muted=true;v.playsInline=true;v.preload='auto';v.src=data;v.onloadeddata=refresh;v.onseeked=()=>frame(base,t);sprites[slot]=v;}else{const im=new Image();im.onload=refresh;im.src=data;sprites[slot]=im;}fx.trialSourceBindings[slot]=slot;await saveAsset(slot,data);refresh();};picker.click();};box.append(replace);const note=document.createElement('p');note.className='sub';note.textContent='Fictional reconstruction; held poses and authored perspective. Separate object and source controls; paper, photo/folder, bars and witness passages are editable. Writing hand is a held photographic pose, not filmed pen performance.';box.append(note);};renderDepotControls();syncDuration();t=Math.min(1,seconds/settings.duration);saveEffects();window.MotionTrial={...api,start,seek};registerCapability('doc-trial',{label:'Interrogation, evidence and trial',category:'Documentary actions',defaults:api.trialDefaults,slots:Object.keys(api.trialSources),render:(c,age,layer)=>api.paintTrial(c,age,sprites,{...fx,...layer.params})});window.motionTrialReady=true;window.dispatchEvent(new Event('motion-trial-ready'));}catch(e){console.error('Trial continuation',e);}})();
